import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import { useTranslation } from 'react-i18next';
import { healthService } from '../services/healthService';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// Fix for default markers in react-leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

const HealthcareMap = () => {
  const { t } = useTranslation();
  const [clinics, setClinics] = useState([]);
  const [userLocation, setUserLocation] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedType, setSelectedType] = useState('');
  const [searchRadius, setSearchRadius] = useState(10000); // 10km default

  // Default location (Pune, Maharashtra)
  const defaultLocation = { lat: 18.5204, lng: 73.8567 };

  useEffect(() => {
    getUserLocation();
  }, []);

  useEffect(() => {
    if (userLocation) {
      fetchNearbyClinics();
    }
  }, [userLocation, selectedType, searchRadius]);

  const getUserLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserLocation({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
        },
        (error) => {
          console.error('Error getting location:', error);
          setUserLocation(defaultLocation);
          setError('Using default location. Please enable location access for better results.');
        }
      );
    } else {
      setUserLocation(defaultLocation);
      setError('Geolocation not supported. Using default location.');
    }
  };

  const fetchNearbyClinics = async () => {
    if (!userLocation) return;

    setLoading(true);
    try {
      const params = {
        maxDistance: searchRadius,
        ...(selectedType && { type: selectedType })
      };
      
      const data = await healthService.getNearbyClinic(
        userLocation.lat,
        userLocation.lng,
        params
      );
      
      setClinics(data.clinics || []);
    } catch (error) {
      console.error('Failed to fetch clinics:', error);
      setError('Failed to load nearby healthcare facilities');
    } finally {
      setLoading(false);
    }
  };

  const getClinicIcon = (type) => {
    const iconColors = {
      hospital: '#dc3545',
      clinic: '#007bff',
      health_center: '#28a745',
      pharmacy: '#ffc107',
      diagnostic_center: '#6f42c1'
    };

    return new L.Icon({
      iconUrl: `data:image/svg+xml;base64,${btoa(`
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="${iconColors[type] || '#007bff'}" width="24" height="24">
          <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/>
        </svg>
      `)}`,
      iconSize: [30, 30],
      iconAnchor: [15, 30],
      popupAnchor: [0, -30]
    });
  };

  const formatDistance = (distance) => {
    if (distance < 1) {
      return `${Math.round(distance * 1000)}m`;
    }
    return `${distance.toFixed(1)}km`;
  };

  const getDirections = (clinic) => {
    const url = `https://www.google.com/maps/dir/?api=1&destination=${clinic.coordinates.latitude},${clinic.coordinates.longitude}`;
    window.open(url, '_blank');
  };

  if (!userLocation) {
    return (
      <div className="loading">
        <div className="spinner"></div>
        <p>Getting your location...</p>
      </div>
    );
  }

  return (
    <div className="container map-container fade-in">
      <div className="card-header text-center">
        <h1 className="card-title">{t('map.nearbyHealthcare')}</h1>
        <p>Find healthcare facilities near you</p>
      </div>

      {error && <div className="alert alert-warning">{error}</div>}

      {/* Filters */}
      <div className="card mb-20">
        <div className="form-row">
          <div className="form-group">
            <label className="form-label">Facility Type</label>
            <select
              className="form-select"
              value={selectedType}
              onChange={(e) => setSelectedType(e.target.value)}
            >
              <option value="">All Types</option>
              <option value="hospital">Hospital</option>
              <option value="clinic">Clinic</option>
              <option value="health_center">Health Center</option>
              <option value="pharmacy">Pharmacy</option>
              <option value="diagnostic_center">Diagnostic Center</option>
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">Search Radius</label>
            <select
              className="form-select"
              value={searchRadius}
              onChange={(e) => setSearchRadius(parseInt(e.target.value))}
            >
              <option value="5000">5 km</option>
              <option value="10000">10 km</option>
              <option value="25000">25 km</option>
              <option value="50000">50 km</option>
            </select>
          </div>

          <div className="form-group">
            <label className="form-label">&nbsp;</label>
            <button className="btn" onClick={fetchNearbyClinics}>
              🔍 Search
            </button>
          </div>
        </div>
      </div>

      <div className="grid grid-2">
        {/* Map */}
        <div className="map-wrapper">
          <MapContainer
            center={[userLocation.lat, userLocation.lng]}
            zoom={12}
            style={{ height: '500px', width: '100%' }}
          >
            <TileLayer
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            />
            
            {/* User location marker */}
            <Marker position={[userLocation.lat, userLocation.lng]}>
              <Popup>
                <strong>Your Location</strong>
              </Popup>
            </Marker>

            {/* Clinic markers */}
            {clinics.map((clinic) => (
              <Marker
                key={clinic._id}
                position={[clinic.coordinates.latitude, clinic.coordinates.longitude]}
                icon={getClinicIcon(clinic.type)}
              >
                <Popup>
                  <div style={{ minWidth: '200px' }}>
                    <h4>{clinic.name}</h4>
                    <p><strong>Type:</strong> {clinic.type.replace('_', ' ')}</p>
                    <p><strong>Distance:</strong> {formatDistance(clinic.distance)}</p>
                    {clinic.contact?.phone && (
                      <p><strong>Phone:</strong> {clinic.contact.phone}</p>
                    )}
                    <button
                      className="btn btn-secondary"
                      onClick={() => getDirections(clinic)}
                      style={{ width: '100%', marginTop: '10px' }}
                    >
                      Get Directions
                    </button>
                  </div>
                </Popup>
              </Marker>
            ))}
          </MapContainer>
        </div>

        {/* Clinic List */}
        <div className="card">
          <div className="card-header">
            <h3 className="card-title">
              Nearby Facilities ({clinics.length})
            </h3>
          </div>

          {loading ? (
            <div className="loading">
              <div className="spinner"></div>
            </div>
          ) : clinics.length === 0 ? (
            <div className="text-center p-20">
              <p>No healthcare facilities found in the selected area.</p>
            </div>
          ) : (
            <div style={{ maxHeight: '400px', overflowY: 'auto' }}>
              {clinics.map((clinic) => (
                <div key={clinic._id} className="queue-item">
                  <div className="queue-patient-info">
                    <div className="queue-patient-name">
                      {clinic.name}
                    </div>
                    <div className="queue-patient-details">
                      <strong>Type:</strong> {clinic.type.replace('_', ' ')} |
                      <strong> Distance:</strong> {formatDistance(clinic.distance)}
                    </div>
                    {clinic.address && (
                      <div className="queue-patient-details">
                        {clinic.address.village}, {clinic.address.district}
                      </div>
                    )}
                    {clinic.contact?.phone && (
                      <div className="queue-patient-details">
                        📞 {clinic.contact.phone}
                      </div>
                    )}
                    {clinic.services && clinic.services.length > 0 && (
                      <div className="queue-patient-details">
                        <strong>Services:</strong> {clinic.services.slice(0, 3).map(s => s.name).join(', ')}
                        {clinic.services.length > 3 && '...'}
                      </div>
                    )}
                  </div>

                  <div className="queue-actions">
                    <button
                      className="btn btn-secondary"
                      onClick={() => getDirections(clinic)}
                    >
                      🗺️ Directions
                    </button>
                    {clinic.contact?.phone && (
                      <button
                        className="btn btn-success"
                        onClick={() => window.open(`tel:${clinic.contact.phone}`)}
                      >
                        📞 Call
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Legend */}
      <div className="card">
        <h4>Map Legend</h4>
        <div className="grid grid-3">
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#dc3545', borderRadius: '50%' }}></div>
            <span>Hospital</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#007bff', borderRadius: '50%' }}></div>
            <span>Clinic</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#28a745', borderRadius: '50%' }}></div>
            <span>Health Center</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#ffc107', borderRadius: '50%' }}></div>
            <span>Pharmacy</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '20px', height: '20px', backgroundColor: '#6f42c1', borderRadius: '50%' }}></div>
            <span>Diagnostic Center</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HealthcareMap;
